def src(key, loc):
    if key in SPK: return {"url": SPK[key], "doi": "", "title": "planning spike " + key.upper(), "version": "this run", "locator": loc, "accessed": A, "tier": 1}
    if key == "in": return {"url": IN, "doi": "", "title": "owner's input file (uncorroborated; counts as zero sources)", "version": "as uploaded", "locator": loc, "accessed": A, "tier": 4}
    if key.startswith("r6-"):
        return {"url": "research/rounds/" + key, "doi": "", "title": "round-6 adversarial review", "version": "this run", "locator": loc, "accessed": A, "tier": 3}
    if key.startswith("r5-"):
        return {"url": "research/rounds/" + key, "doi": "", "title": "round-5 adversarial review", "version": "this run", "locator": loc, "accessed": A, "tier": 3}
    if key.startswith("r4-"):
        return {"url": "research/rounds/" + key, "doi": "", "title": "round-4 adversarial review", "version": "this run", "locator": loc, "accessed": A, "tier": 3}
    if key.startswith("r3-"):
        return {"url": "research/rounds/" + key, "doi": "", "title": "round-3 adversarial review (sources read in full where it says so)", "version": "this run", "locator": loc, "accessed": A, "tier": 3}
    if key.startswith("K-") or key.startswith("r1-"):
        return {"url": key, "doi": "", "title": "knowledge item from the store" if key.startswith("K-") else "round-1 worker file (sources read at snippet level; see that file)", "version": "", "locator": loc, "accessed": A, "tier": 3 if key.startswith("K-") else 4}
    u, doi, title, _, ver, tier, *_ = S[key]
    return {"url": u, "doi": doi, "title": title, "version": ver, "locator": loc, "accessed": A, "tier": tier}
