def edit(cid, **kw):
    c = next(x for x in C if x["id"] == cid)
    for k, v in kw.items():
        if k == "add_sources": c["sources"] += [src(a, b) for a, b in v]
        elif k == "add_note": c["note"] = (c["note"] + " " + v).strip()
        else: c[k] = v
